oxy_webhelp_navlinks = {"mdb_recover-d39536e37232":{"topics":[{"title":"MongoDB cross-version compatibility","shortdesc":"<p class=\"shortdesc\">Recovery behavior between MongoDB versions varies based on whether the version         difference is at the patch, minor, or major level.<\/p>","href":"mongodb\/mdb_cross_version_compatibility.html","attributes":{"data-id":"mdb_cross_version_compatibility"},"menu":{"hasChildren":false},"tocID":"mdb_cross_version_compatibility-d39536e37243","topics":[]},{"title":"MongoDB point-in-time recovery","shortdesc":"<p class=\"shortdesc\">You can use point-in-time recovery for MongoDB to restore your data to a specific         point in time, ensuring data consistency and accuracy.<\/p>","href":"mongodb\/mongodb_point_in_time_recovery.html","attributes":{"data-id":"mongodb_point_in_time_recovery"},"menu":{"hasChildren":false},"tocID":"mongodb_point_in_time_recovery-d39536e37254","topics":[]},{"title":"Recoverable range for MongoDB sources","shortdesc":"<p class=\"shortdesc\">The recoverable range of a MongoDB source with physical backup and recovery using Ops         Manager integration is a visual representation of the period of time during which you can         recover a source to a specific point in time.<\/p>","href":"mongodb\/recoverable_range_mdb_source.html","attributes":{"data-id":"recoverable_range_mdb_source"},"menu":{"hasChildren":false},"tocID":"recoverable_range_mdb_source-d39536e37265","topics":[]},{"title":"Recoverable range for MongoDB databases and collections","shortdesc":"<p class=\"shortdesc\">The recoverable range is a visual representation of the period during which you can         recover a database or a collection to a specific point in time.<\/p>","href":"mongodb\/recoverable_range_mongodb_db_collection.html","attributes":{"data-id":"recoverable_range_mongodb_db_collection"},"menu":{"hasChildren":false},"tocID":"recoverable_range_mongodb_db_collection-d39536e37276","topics":[]},{"title":"Recovering a batch of MongoDB databases","shortdesc":"<p class=\"shortdesc\">Recover a batch of MongoDB databases by retrieving specific data from a backup source         if you are overwriting an original collection or duplicating it in the same or another         MongoDB source. This might be used in cases such as data loss or system         corruption.<\/p>","href":"mongodb\/recovering_batch_mongodb_db.html","attributes":{"data-id":"recovering_batch_mongodb_db"},"menu":{"hasChildren":false},"tocID":"recovering_batch_mongodb_db-d39536e37287","topics":[]},{"title":"Recovering the MongoDB Admin DB object","shortdesc":"<p class=\"shortdesc\">Recover the Admin DB object of a MongoDB source to return the custom roles and users         of the source to the state in a selected snapshot.<\/p>","href":"mongodb\/recovering_mongodb_admin_db.html","attributes":{"data-id":"recovering_mongodb_admin_db"},"menu":{"hasChildren":false},"tocID":"recovering_mongodb_admin_db-d39536e37298","topics":[]},{"title":"Recovering a MongoDB collection","shortdesc":"<p class=\"shortdesc\">Recover a MongoDB collection by retrieving specific data from a backup source if you         are overwriting an original collection or duplicating it in the same or another MongoDB         source. This might be used in cases such as data loss or system corruption.<\/p>","href":"mongodb\/recovering_mongodb_collection.html","attributes":{"data-id":"recovering_mongodb_collection"},"menu":{"hasChildren":false},"tocID":"recovering_mongodb_collection-d39536e37309","topics":[]},{"title":"Recovering a batch of MongoDB collections","shortdesc":"<p class=\"shortdesc\">Recover a batch of MongoDB collections by retrieving specific data from a backup         source if you are overwriting an original collection or duplicating it in the same or         another MongoDB source. You might use this in cases of a data loss or system         corruption.<\/p>","href":"mongodb\/recovering_batch_mongodb_collections.html","attributes":{"data-id":"recovering_batch_mongodb_collections"},"menu":{"hasChildren":false},"tocID":"recovering_batch_mongodb_collections-d39536e37320","topics":[]},{"title":"Recovering MongoDB sources managed by Ops Manager","shortdesc":"<p class=\"shortdesc\">Recover a MongoDB source managed through the physical backup and recovery using Ops         Manager integration by retrieving specific data from a backup source, whether you are         overwriting the original source or restoring it to another MongoDB source.<\/p>","href":"mongodb\/recovering_mdb_src_ops_mgr.html","attributes":{"data-id":"recovering_mdb_src_ops_mgr"},"menu":{"hasChildren":false},"tocID":"recovering_mdb_src_ops_mgr-d39536e37331","topics":[]}]}};